template <typename T>
constexpr T process(T val) {
    if constexpr (std::is_integral_v<T>) {
        // Compile-time path selected: Fast integer handling
        return val * 4;
    } else {
        // Compile-time path selected: Generic/float handling
        return val + val + val + val;
    }
}

constexpr int val_i = process(10);
constexpr double val_d = process(5.0);
